select *
from t_feedback


        AND (
        feedback_content ILIKE CONCAT('%', #{query.searchWord}, '%')
        OR user_name ILIKE CONCAT('%', #{query.searchWord}, '%')
        )


        AND TO_CHAR(create_time, 'YYYY-MM-DD') >= #{query.startDate}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') <= #{query.endDate}



    order by create_time desc
